import{_ as t,o as a,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Ceph Days NYC 2023: Why We Built A “Message-Driven Telemetry System At Scale” Ceph Cluster","description":"","frontmatter":{"title":"Ceph Days NYC 2023: Why We Built A “Message-Driven Telemetry System At Scale” Ceph Cluster","date":"2023-05-17T00:00:00.000Z","updated":"2023-05-18T00:00:00.000Z","tags":["Ceph","Telemetry System","Distributed Storage","Storage Engineering","Bloomberg"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Days_NYC_2023_-_Why_We_Built_A_Message-Driven_Telemetry_System_At_Scale_Ceph_Cluster.md","filePath":"posts/2023/Ceph_Days_NYC_2023_-_Why_We_Built_A_Message-Driven_Telemetry_System_At_Scale_Ceph_Cluster.md","lastUpdated":1780459816000}'),s={name:"posts/2023/Ceph_Days_NYC_2023_-_Why_We_Built_A_Message-Driven_Telemetry_System_At_Scale_Ceph_Cluster.md"};function i(o,e,_,n,h,p){return a(),l("div",null,[...e[0]||(e[0]=[r('<p>Nathan Howard，Bloomberg的高级软件工程师，在Ceph Days NYC 2023会议上分享了Bloomberg如何构建一个大规模的“消息驱动型遥测系统”。以下是会议内容的要点总结：</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>Nathan Howard是Bloomberg分布式存储团队的一员，负责设计和维护软件定义存储，特别是基于Ceph的对象级存储（S3 API，内部称为Bloomberg Cloud Storage 或 BCS）。</p><h3 id="会议议程" tabindex="-1">会议议程 <a class="header-anchor" href="#会议议程" aria-label="Permalink to &quot;会议议程&quot;">​</a></h3><ol><li><strong>公司介绍</strong>：Bloomberg是一家全球性的金融科技公司，拥有超过350万订阅者，每日处理数百亿条数据。</li><li><strong>存储工程团队介绍</strong>：负责设计、构建和维护所有存储系统，包括文件、块和对象存储，以及数据保护和存储工作流程自动化。</li><li><strong>集群信息</strong>：介绍了LCF集群的详细信息，包括数据中心分布、租户数量、存储容量和OSD数量。</li><li><strong>Ceph默认Telemetry系统的问题</strong>：讨论了Ceph默认集成的Prometheus系统的局限性，尤其是在大规模集群中的性能问题和缺乏用户级指标。</li><li><strong>解决方案要求</strong>：提出了实时性、可扩展性、集成Grafana和易于扩展等要求。</li><li><strong>解决方案概述</strong>：介绍了基于发布-订阅模型的解决方案，使用RabbitMQ作为消息代理，Celery作为任务调度器，Python编写，易于扩展和维护。</li><li><strong>技术栈细节</strong>：详细介绍了RabbitMQ和Celery的使用，以及如何通过这些技术实现高可扩展性和容错性。</li><li><strong>代码示例</strong>：展示了如何使用Celery进行任务调度和消息传递。</li><li><strong>结果和未来计划</strong>：讨论了解决方案的实际效果，包括快速响应、良好资源利用和易于扩展，并提出了未来可能的改进方向，如扩展到RBD和收集元数据指标。</li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>确定了解决Ceph Telemetry系统问题的技术方案，使用RabbitMQ和Celery构建分布式任务调度系统。</li><li>确认了集成Grafana进行数据可视化和监控。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>继续优化和扩展当前的Telemetry系统，以支持更多的存储类型和更细粒度的指标。</li><li>考虑将解决方案贡献给开源社区，以帮助其他Ceph用户。</li><li>招聘更多人才，以支持公司内部Ceph和其他技术的开发和维护。</li></ul><h3 id="改进点" tabindex="-1">改进点 <a class="header-anchor" href="#改进点" aria-label="Permalink to &quot;改进点&quot;">​</a></h3><ul><li>原总结中未提及LCF集群的具体信息。</li><li>原总结中对Ceph默认Telemetry系统问题的描述不够详细。</li><li>原总结中对解决方案的技术细节描述不够全面。</li></ul><p>通过以上分析和改进，我们确保了总结的准确性和完整性，并保留了所有相关的Ceph和相关领域的英文原文关键词。</p>',12)])])}const g=t(s,[["render",i]]);export{m as __pageData,g as default};
